/**
 * guardian init — first-time setup wizard
 * Creates ~/.guardian-layer/ with config.json + starter policy
 */

import { existsSync, writeFileSync } from 'node:fs'
import { createInterface } from 'node:readline'
import { ensureConfigDir, getConfigDir, getConfigPath, saveConfig, defaultConfig } from '../config.js'

const STARTER_POLICY = `# Guardian Layer Policy
# Generated by: guardian init
#
# Edit this file to control what AI agents can access.
# Docs: https://guardian-layer.dev/policy-reference

agents:
  default-agent:
    accounts:
      visible: []          # Set account IDs or leave empty for all
      hidden: []
    transactions:
      visible: true
      max_lookback_days: 30
    spending:
      enabled: false       # Require explicit enable + limits
    escalation:
      enabled: true
      notify_webhook: ""   # Optional: POST JSON on escalation
`

async function prompt(rl: ReturnType<typeof createInterface>, question: string): Promise<string> {
  return new Promise(resolve => rl.question(question, resolve))
}

export async function initCommand(): Promise<void> {
  const dir = getConfigDir()
  const configPath = getConfigPath()
  const defaults = defaultConfig()

  console.log('\n🛡️  Guardian Layer Setup\n')

  if (existsSync(configPath)) {
    const rl = createInterface({ input: process.stdin, output: process.stdout })
    const answer = await prompt(rl, `Config already exists at ${configPath}. Overwrite? [y/N] `)
    rl.close()
    if (answer.toLowerCase() !== 'y') {
      console.log('Aborted.')
      return
    }
  }

  ensureConfigDir()

  // Write starter policy if it doesn't exist
  const policyPath = defaults.policy_path
  if (!existsSync(policyPath)) {
    writeFileSync(policyPath, STARTER_POLICY, 'utf-8')
    console.log(`✓ Created starter policy: ${policyPath}`)
  } else {
    console.log(`  Policy already exists: ${policyPath}`)
  }

  // Save config
  saveConfig(defaults)
  console.log(`✓ Config written: ${configPath}`)
  console.log(`\nConfig directory: ${dir}`)
  console.log('\nNext steps:')
  console.log('  1. Edit your policy:  ' + policyPath)
  console.log('  2. Validate it:       guardian policy validate')
  console.log('  3. Start the server:  guardian start')
  console.log('\nFor Claude Desktop integration, add to your MCP settings:')
  console.log('  "guardian-layer": { "command": "guardian", "args": ["start"] }\n')
}
